insert into public.learning_cards (lesson_id, position, title, blocks) values ('4eeb2474-1735-58da-bf8f-c0b72d55d3b0', 1, 'Un championnat du monde', '[{"type":"keyfigure","value":"1950","label":"Première course du championnat, à Silverstone"},{"type":"text","text":"La Formule 1 est le championnat du monde de monoplaces le plus prestigieux. Ses règles sont fixées par la FIA, la Fédération internationale de l’automobile."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('4eeb2474-1735-58da-bf8f-c0b72d55d3b0', 2, 'Deux titres', '[{"type":"list","items":["Le titre pilotes récompense le meilleur pilote de la saison.","Le titre constructeurs récompense la meilleure écurie, en additionnant les points de ses deux pilotes. Il existe depuis 1958."]},{"type":"fact","text":"Le premier champion du monde est l’Italien Giuseppe Farina, en 1950, sur Alfa Romeo."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('4eeb2474-1735-58da-bf8f-c0b72d55d3b0', 3, 'Le plateau', '[{"type":"keyfigure","value":"11","label":"écuries en 2026, avec l’arrivée de Cadillac"},{"type":"text","text":"Chaque écurie engage deux pilotes, soit 22 voitures au départ de chaque Grand Prix en 2026."}]'::jsonb);
