insert into public.learning_cards (lesson_id, position, title, blocks) values ('31f0dfbe-2af4-5236-884a-1db30599c2a8', 1, 'Trois temps forts', '[{"type":"list","items":["Les essais libres : les écuries règlent la voiture.","Les qualifications : elles fixent l’ordre de la grille de départ.","La course, le dimanche."]},{"type":"text","text":"Certains week-ends ajoutent une course sprint d’environ 100 km le samedi."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('31f0dfbe-2af4-5236-884a-1db30599c2a8', 2, 'Les qualifications', '[{"type":"text","text":"Elles se déroulent en trois phases : Q1 et Q2 éliminent les plus lents, puis les 10 meilleurs se disputent la pole position en Q3."},{"type":"keyfigure","value":"10","label":"pilotes en Q3"}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('31f0dfbe-2af4-5236-884a-1db30599c2a8', 3, 'La course', '[{"type":"keyfigure","value":"305 km","label":"distance minimale d’un Grand Prix (environ 260 km à Monaco)"},{"type":"text","text":"Une course ne peut pas dépasser 2 heures de course : si la distance n’est pas atteinte, le drapeau à damier tombe quand même."}]'::jsonb);
