insert into public.learning_cards (lesson_id, position, title, blocks) values ('da4f7ee6-bf65-5bb4-8b54-87ecd62ad5bb', 2, 'Spa et Silverstone', '[{"type":"list","items":["Spa-Francorchamps (Belgique) : environ 7 km et l’enchaînement Eau Rouge – Raidillon.","Silverstone (Royaume-Uni) : là où tout a commencé, en 1950."]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('da4f7ee6-bf65-5bb4-8b54-87ecd62ad5bb', 3, 'Suzuka', '[{"type":"text","text":"Au Japon, Suzuka est le seul circuit du calendrier dont le tracé forme un huit : la piste passe sous elle-même grâce à un pont."}]'::jsonb);
