insert into public.learning_cards (lesson_id, position, title, blocks) values ('48300c08-74c9-5f3f-872e-f28282f6588a', 1, 'Permanent ou urbain', '[{"type":"text","text":"Un circuit permanent est construit pour la course. Un circuit urbain utilise des routes publiques fermées pour l’occasion."},{"type":"list","items":["Urbains : Monaco, Singapour, Bakou, Las Vegas","Permanents : Silverstone, Spa, Suzuka, Monza"]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('48300c08-74c9-5f3f-872e-f28282f6588a', 2, 'Courir la nuit', '[{"type":"keyfigure","value":"2008","label":"première course de nuit, à Singapour"},{"type":"text","text":"Depuis 2023, Las Vegas accueille aussi une course de nuit, sur le Strip."}]'::jsonb);
