insert into public.learning_cards (lesson_id, position, title, blocks) values ('7fa76311-ee16-5b1a-b506-62227f3418b9', 1, 'Appui ou vitesse', '[{"type":"text","text":"Un circuit lent et sinueux comme Monaco demande un maximum d’appui aérodynamique. Un circuit rapide comme Monza pousse au contraire à réduire l’appui pour gagner en vitesse de pointe."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('7fa76311-ee16-5b1a-b506-62227f3418b9', 2, 'Des conditions extrêmes', '[{"type":"keyfigure","value":"2 200 m","label":"altitude du circuit de Mexico, la plus élevée du calendrier"},{"type":"text","text":"L’air raréfié y réduit l’appui et le refroidissement."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('7fa76311-ee16-5b1a-b506-62227f3418b9', 3, 'Le sens de rotation', '[{"type":"fact","text":"Interlagos, au Brésil, se parcourt dans le sens inverse des aiguilles d’une montre : les cous des pilotes travaillent à l’envers."}]'::jsonb);
