insert into public.learning_cards (lesson_id, position, title, blocks) values ('69c4bc56-62bf-5d66-9d60-5092fac1575b', 1, 'Un seul fournisseur', '[{"type":"keyfigure","value":"2011","label":"Pirelli devient le fournisseur unique de la F1"},{"type":"text","text":"Toutes les écuries disposent donc des mêmes pneus. La différence se fait dans la façon de les utiliser."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('69c4bc56-62bf-5d66-9d60-5092fac1575b', 2, 'Les pneus secs', '[{"type":"swatches","items":[{"label":"Tendre","color":"#E0301E","text":"Le plus rapide, s’use vite"},{"label":"Médium","color":"#F2C200","text":"Le compromis"},{"label":"Dur","color":"#F2F2F2","text":"Le plus durable, moins rapide"}]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('69c4bc56-62bf-5d66-9d60-5092fac1575b', 3, 'La pluie et la règle des deux gommes', '[{"type":"swatches","items":[{"label":"Intermédiaire","color":"#1F9D55","text":"Piste humide"},{"label":"Pluie","color":"#1C6BFF","text":"Piste détrempée"}]},{"type":"text","text":"Sur le sec, chaque pilote doit utiliser au moins deux types de pneus secs en course : au moins un arrêt au stand est donc obligatoire."}]'::jsonb);
