delete from public.lesson_items where lesson_id = '43a2948a-82a6-5d97-b3cc-49016788e9e9';
insert into public.learning_cards (lesson_id, position, title, blocks) values ('43a2948a-82a6-5d97-b3cc-49016788e9e9', 1, 'L’arrêt au stand', '[{"type":"keyfigure","value":"2 à 3 s","label":"pour changer les quatre pneus"},{"type":"text","text":"Le passage complet par la voie des stands, limitée le plus souvent à 80 km/h, coûte environ une vingtaine de secondes."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('43a2948a-82a6-5d97-b3cc-49016788e9e9', 2, 'L’undercut', '[{"type":"text","text":"S’arrêter avant son rival : avec des pneus neufs, on boucle des tours plus rapides pendant qu’il roule sur des pneus usés. Quand il s’arrête à son tour, on peut ressortir devant."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('43a2948a-82a6-5d97-b3cc-49016788e9e9', 3, 'L’overcut', '[{"type":"text","text":"L’inverse : rester en piste plus longtemps et s’arrêter après lui. Ça marche quand les pneus neufs mettent du temps à chauffer ou quand le rival ressort dans le trafic."}]'::jsonb);
insert into public.lesson_items (lesson_id, position, question_id) values ('43a2948a-82a6-5d97-b3cc-49016788e9e9', 1, 'fabe32ce-9ee4-5242-99ea-a55b033055b0');
