insert into public.learning_cards (lesson_id, position, title, blocks) values ('5da57807-a5a2-5e5b-a0ae-12804bb876c4', 1, 'Neutraliser la course', '[{"type":"list","items":["Safety Car : une voiture entre en piste, les pilotes la suivent en file sans dépasser.","VSC (voiture de sécurité virtuelle, depuis 2015) : tout le monde ralentit à une vitesse imposée, sans voiture en piste."]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('5da57807-a5a2-5e5b-a0ae-12804bb876c4', 2, 'Les drapeaux', '[{"type":"swatches","items":[{"label":"Jaune","color":"#F2C200","text":"Danger, dépassement interdit"},{"label":"Bleu","color":"#1C6BFF","text":"Laisser passer un pilote qui te prend un tour"},{"label":"Rouge","color":"#E0301E","text":"Séance arrêtée"}]},{"type":"text","text":"Le drapeau à damier marque la fin de la course. Le drapeau noir signifie une disqualification."}]'::jsonb);
